import { useEffect, useState } from "react";
import axios from "axios";

const API = "http://localhost:5000";

function App() {
  const [candidates, setCandidates] = useState([]);
  const [token, setToken] = useState(localStorage.getItem("token"));
  const [role, setRole] = useState(localStorage.getItem("role"));

  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");

  const [newCandidate, setNewCandidate] = useState({
    name: "",
    position: "",
    description: ""
  });

  // Fetch candidates
  const fetchCandidates = async () => {
    const res = await axios.get(`${API}/api/candidates`);
    setCandidates(res.data);
  };

  useEffect(() => {
    fetchCandidates();
  }, []);

  // LOGIN
  const login = async () => {
    const res = await axios.post(`${API}/api/auth/login`, {
      email,
      password
    });

    localStorage.setItem("token", res.data.token);
    localStorage.setItem("role", res.data.role);

    setToken(res.data.token);
    setRole(res.data.role);
    alert("Login Success");
  };

  // VOTE
  const vote = async (id) => {
    await axios.post(
      `${API}/api/vote/${id}`,
      {},
      { headers: { Authorization: `Bearer ${token}` } }
    );

    alert("Vote Successful");
    fetchCandidates();
  };

  // ADD CANDIDATE (ADMIN)
  const addCandidate = async () => {
    await axios.post(`${API}/api/candidates`, newCandidate, {
      headers: { Authorization: `Bearer ${token}` }
    });

    alert("Candidate Added");
    fetchCandidates();
  };

  return (
    <div style={{ padding: 20 }}>
      <h1>Voting System</h1>

      {/* LOGIN */}
      {!token && (
        <div>
          <h2>Login</h2>
          <input
            placeholder="Email"
            onChange={(e) => setEmail(e.target.value)}
          />
          <br />
          <input
            type="password"
            placeholder="Password"
            onChange={(e) => setPassword(e.target.value)}
          />
          <br />
          <button onClick={login}>Login</button>
        </div>
      )}

      {/* ADMIN PANEL */}
      {role === "admin" && (
        <div>
          <h2>Add Candidate (Admin)</h2>
          <input
            placeholder="Name"
            onChange={(e) =>
              setNewCandidate({ ...newCandidate, name: e.target.value })
            }
          />
          <br />
          <input
            placeholder="Position"
            onChange={(e) =>
              setNewCandidate({ ...newCandidate, position: e.target.value })
            }
          />
          <br />
          <input
            placeholder="Description"
            onChange={(e) =>
              setNewCandidate({ ...newCandidate, description: e.target.value })
            }
          />
          <br />
          <button onClick={addCandidate}>Add</button>
        </div>
      )}

      {/* CANDIDATE LIST */}
      <h2>Candidates</h2>
      {candidates.map((c) => (
        <div key={c._id} style={{ border: "1px solid gray", margin: 10, padding: 10 }}>
          <h3>{c.name}</h3>
          <p>{c.position}</p>
          <p>{c.description}</p>
          <p>Votes: {c.votes}</p>

          {token && role === "user" && (
            <button onClick={() => vote(c._id)}>Vote</button>
          )}
        </div>
      ))}
    </div>
  );
}

export default App;
